def minimumNumbers(num: int, k: int) -> int:
    # If num is 0, we can use the empty set
    if num == 0:
        return 0

    # Try n from 1 to 10 (units digits cycle every 10)
    for n in range(1, 11):
        # n*k must not exceed num, and the remainder must be divisible by 10
        if n * k > num:
            break
        if (num - n * k) % 10 == 0:
            return n
    return -1
